{"nl": "show disk usage for every mounted filesystem", "bash": "df -h"}
{"nl": "show disk usage in human-readable format sorted by size", "bash": "df -h | sort -k5 -rh"}
{"nl": "check how much space the /var directory is using", "bash": "du -sh /var"}
{"nl": "find the top 10 largest directories under /home", "bash": "du -h /home | sort -rh | head -10"}
{"nl": "find the top 10 largest files on the entire filesystem", "bash": "find / -type f -printf '%s %p\\n' 2>/dev/null | sort -rn | head -10"}
{"nl": "show inode usage for all filesystems", "bash": "df -i"}
{"nl": "check which filesystem a file belongs to", "bash": "df -h /var/log/syslog"}
{"nl": "add 4GB of swap space", "bash": "sudo fallocate -l 4G /swapfile && sudo chmod 600 /swapfile && sudo mkswap /swapfile && sudo swapon /swapfile"}
{"nl": "show current swap usage", "bash": "swapon --show"}
{"nl": "disable and remove the current swapfile", "bash": "sudo swapoff /swapfile && sudo rm /swapfile"}

